                )}
              </button>

              <p className="text-[10px] text-center text-slate-400 mt-2">
                🔒 Protected by 256-Bit SSL Encryption & Escrow Safeguard
              </p>
            </div>
          </div>
        </form>
      )}
    </div>
  );
}

