          <div className="w-16 h-16 bg-rose-500/10 rounded-2xl flex items-center justify-center text-rose-500 mx-auto mb-6 border border-rose-500/20">
            <ShieldAlert className="w-8 h-8" />
          </div>
          <h1 className="text-xl font-black mb-2">Access Denied</h1>
          <p className="text-xs text-gray-400 mb-6">Strict Dashboard Isolation is active. You do not have permission to view the Delivery Portal.</p>
          <button onClick={() => router.push('/')} className="bg-white/5 border border-white/5 text-slate-350 hover:text-white font-black text-xs px-6 py-3 rounded-2xl block w-full cursor-pointer">
            Back to Homepage
          </button>
        </div>
      </div>
    );
  }

  const handleUpdateStatus = (taskId: string, newStatus: string) => {
    setTasks(prev => prev.map(t => {
      if (t.id === taskId) {
        // If delivered, update earnings and cash in hand
        if (newStatus === 'DELIVERED') {
          setDeliveredCount(c => c + 1);
          setEarnings(e => e + 120); // 120 BDT delivery fee
          if (t.codAmount > 0) {
            setCashInHand(ch => ch + t.codAmount);
          }
        }
        return { ...t, status: newStatus };
      }
      return t;
    }));

    // Simulate real-time websocket/SSE notifications
    alert(`Order ${taskId} status updated to ${newStatus}. Notifications sent to Customer and Seller.`);
  };

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      {/* Header Banner */}
      <header className="bg-[#1F2937] text-white py-10 px-4 md:px-8 border-b border-gray-800">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div>
            <div className="flex items-center gap-2">
              <span className="bg-[#FFC107] text-[#1F2937] text-[10px] font-black uppercase tracking-widest px-2.5 py-1 rounded-full">
                Courier & Logistics Portal
              </span>
            </div>
            <h1 className="text-3xl font-black mt-2">Courier Dashboard: {username || 'Delivery Agent'}</h1>
            <p className="text-xs text-gray-400 mt-1">Accept shipments, track delivery coordinates, and manage cash collection logs.</p>
          </div>
          <button
            onClick={() => { logout(); window.location.href = '/login'; }}
            className="flex items-center gap-1.5 border border-red-500/30 text-red-400 hover:bg-red-500/10 text-xs font-bold px-4 py-2.5 rounded-xl transition-all cursor-pointer"
          >
            <LogOut className="w-4 h-4" />
            Sign Out
          </button>
        </div>
      </header>

      {/* Main Container */}
      <div className="max-w-7xl mx-auto px-4 md:px-8 mt-8 grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Left Column: Stats & Map */}
        <div className="lg:col-span-1 space-y-6">
          {/* Stats grid */}
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white border border-gray-200 p-5 rounded-2xl shadow-sm">
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">Completed Deliveries</p>
              <p className="text-2xl font-black text-[#1F2937] mt-1">{deliveredCount}</p>
            </div>
            <div className="bg-white border border-gray-200 p-5 rounded-2xl shadow-sm">
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">Courier Earnings</p>
              <p className="text-2xl font-black text-green-600 mt-1">${earnings}</p>
            </div>
            <div className="bg-white border border-gray-200 p-5 rounded-2xl shadow-sm col-span-2">
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider font-semibold">Cash in Hand (COD)</p>
              <p className="text-2xl font-black text-[#1F2937] mt-1">${cashInHand}</p>
              <span className="text-[8px] text-gray-400 block mt-1">Please deposit COD amount to Delivery Manager weekly.</span>
            </div>
          </div>

          {/* Interactive Routing Coordinates */}
          <div className="bg-white border border-gray-200 rounded-2xl shadow-sm overflow-hidden p-5 space-y-3">
            <h3 className="font-black text-[#1F2937] text-sm flex items-center gap-1.5">
              <Map className="w-4.5 h-4.5 text-[#FF8F00]" />
              Live Routing Map Coordinates
            </h3>
            <div className="bg-gray-100 rounded-xl h-48 flex items-center justify-center border border-gray-200 text-center relative overflow-hidden">
              <div className="absolute inset-0 bg-cover bg-center opacity-30" style={{ backgroundImage: "url('https://images.unsplash.com/photo-1524661135-423995f22d0b?w=600&auto=format&fit=crop&q=60')" }} />
              <div className="relative z-10 p-4">
                <Navigation className="w-8 h-8 text-[#FF8F00] mx-auto mb-2 animate-bounce" />
                <span className="text-[10px] font-bold text-gray-800">Map Rendering Sandbox</span>
                <p className="text-[9px] text-gray-500 mt-1 max-w-[200px] mx-auto">Dhaka Metropolitan Grid routing enabled. Dispatch coords synced.</p>
              </div>
            </div>
          </div>
        </div>

        {/* Right Column: Assigned Shipments */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white border border-gray-200 rounded-2xl shadow-sm p-6 space-y-4">
            <h3 className="font-black text-[#1F2937] text-base flex items-center gap-2">
              <Truck className="w-5 h-5 text-[#FF8F00]" />
              Active Shipments Assigned ({tasks.filter(t => t.status !== 'DELIVERED').length})
            </h3>

            <div className="space-y-4">
              {tasks.filter(t => t.status !== 'DELIVERED').map(task => (
                <div key={task.id} className="p-5 border border-gray-100 bg-gray-50 rounded-xl space-y-4">
                  <div className="flex justify-between items-start border-b border-gray-200/60 pb-3">
                    <div>
                      <span className="font-mono text-xs font-black text-gray-900">{task.id}</span>
                      <span className="text-[9px] text-gray-400 block mt-0.5">Method: {task.paymentMethod}</span>
                    </div>
                    <span className={`text-[8.5px] font-black px-2.5 py-1 border rounded-full uppercase ${
                      task.status === 'ASSIGNED' ? 'bg-yellow-100 text-yellow-700 border-yellow-200' :
                      task.status === 'SHIPPED' ? 'bg-blue-100 text-blue-700 border-blue-200' :
                      'bg-orange-100 text-orange-700 border-orange-200'
                    }`}>
                      {task.status}
                    </span>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-[10px] font-semibold text-gray-600">
                    <div className="space-y-2">
                      <p className="flex items-center gap-1.5">
                        <MapPin className="w-3.5 h-3.5 text-gray-400 shrink-0" />
                        <span>Address: <span className="font-bold text-gray-800">{task.address}</span></span>
                      </p>
                      <p className="flex items-center gap-1.5">
                        <Phone className="w-3.5 h-3.5 text-gray-400 shrink-0" />
                        <span>Phone: <span className="font-bold text-gray-800">{task.phone}</span></span>
                      </p>
                    </div>

                    <div className="space-y-2 md:text-right">
                      <p>
                        <span>Collect COD: <span className="text-sm font-black text-[#1F2937]">৳{task.codAmount}</span></span>
                      </p>
                      <p className="text-[9px] text-gray-400 italic">Notes: "{task.notes}"</p>
                    </div>
                  </div>

                  <div className="flex flex-wrap gap-2 border-t border-gray-200/60 pt-3">
                    {task.status === 'ASSIGNED' && (
                      <button
                        onClick={() => handleUpdateStatus(task.id, 'SHIPPED')}
                        className="bg-[#1F2937] hover:bg-black text-white text-[10px] font-bold px-4 py-2 rounded-lg transition-colors cursor-pointer"
                      >
                        Accept & Start Shipping
                      </button>
                    )}
                    {task.status === 'SHIPPED' && (
                      <button
                        onClick={() => handleUpdateStatus(task.id, 'PICKED_UP')}
                        className="bg-blue-600 hover:bg-blue-700 text-white text-[10px] font-bold px-4 py-2 rounded-lg transition-colors cursor-pointer"
                      >
                        Mark Out For Delivery
                      </button>
                    )}
                    {(task.status === 'PICKED_UP' || task.status === 'SHIPPED') && (
                      <>
                        <button
                          onClick={() => handleUpdateStatus(task.id, 'DELIVERED')}
                          className="bg-[#FFC107] hover:bg-[#FFB300] text-[#1F2937] text-[10px] font-black px-4 py-2 rounded-lg transition-colors cursor-pointer"
                        >
                          Confirm Delivered
                        </button>
                        <button
                          onClick={() => handleUpdateStatus(task.id, 'FAILED')}
                          className="border border-red-500/20 text-red-500 hover:bg-red-500/5 text-[10px] font-bold px-4 py-2 rounded-lg transition-colors cursor-pointer"
                        >
                          Mark Delivery Failed
                        </button>
                      </>
                    )}
                  </div>
                </div>
              ))}

              {tasks.filter(t => t.status !== 'DELIVERED').length === 0 && (
                <div className="text-center py-12 text-gray-400 space-y-2">
                  <Inbox className="w-10 h-10 mx-auto text-gray-300" />
                  <p className="text-xs font-bold">No pending deliveries</p>
                  <p className="text-[10px] text-gray-400">All shipments have been successfully dispatched and delivered.</p>
                </div>
              )}
            </div>
          </div>
        </div>

      </div>
    </main>
  );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { Mail, Loader2, AlertCircle, CheckCircle2, ArrowLeft, Send } from 'lucide-react';

type PageState = 'idle' | 'loading' | 'success' | 'error';

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState('');
  const [pageState, setPageState] = useState<PageState>('idle');
  const [errorMsg, setErrorMsg] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) {
      setPageState('error');
      setErrorMsg('Please enter your email address.');
      return;
    }
    setErrorMsg('');
    setPageState('loading');

    try {
      const res = await fetch('/api/auth/forgot-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      });
      const data = await res.json();
      if (!res.ok) {
        setErrorMsg(data.error || data.message || 'Failed to send reset link. Please try again.');
        setPageState('error');
        return;
      }
      setPageState('success');
    } catch {
      setErrorMsg('Could not connect to the server. Please try again later.');
      setPageState('error');
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center relative overflow-hidden bg-neutral-dark">
      {/* Animated background */}
      <div className="absolute inset-0 z-0">
        <div className="absolute inset-0 bg-gradient-to-br from-gray-900 via-gray-800 to-gray-950" />
        <div className="absolute top-[-10%] left-[20%] w-[400px] h-[400px] rounded-full bg-primary/10 blur-[100px] animate-pulse" />
        <div className="absolute bottom-[-5%] right-[10%] w-[350px] h-[350px] rounded-full bg-primary/5 blur-[80px] animate-pulse" style={{ animationDelay: '1s' }} />
      </div>
      <div className="absolute inset-0 z-0 opacity-5"
        style={{
          backgroundImage: 'linear-gradient(rgba(255,193,7,0.3) 1px, transparent 1px), linear-gradient(90deg, rgba(255,193,7,0.3) 1px, transparent 1px)',
          backgroundSize: '40px 40px'
        }}
      />

      <div className="relative z-10 w-full max-w-md px-4">
        {/* Branding */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-primary shadow-glow mb-4">
            <span className="text-3xl font-black text-gray-900">Z</span>
          </div>
          <h1 className="text-3xl font-black text-primary tracking-tight">Zibonbaba</h1>
          <p className="text-gray-400 text-sm mt-1">Account Recovery</p>
        </div>

        {/* Glass Card */}
        <div className="backdrop-blur-xl bg-white/5 border border-white/10 rounded-xl shadow-modal p-8">
          {pageState === 'success' ? (
            /* Success State */
            <div className="text-center py-4">
              <div className="w-20 h-20 bg-green-500/20 border border-green-500/30 rounded-full flex items-center justify-center mx-auto mb-6">
                <CheckCircle2 size={40} className="text-green-400" />
              </div>
              <h2 className="text-xl font-bold text-white mb-2">Check Your Email</h2>
              <p className="text-gray-400 text-sm mb-2">
                Password reset link sent to your email
              </p>
              <p className="text-primary font-medium text-sm mb-8 break-all">{email}</p>
              <p className="text-gray-500 text-xs mb-8">
                If you don&apos;t see it, please check your spam folder. The link expires in 30 minutes.
              </p>
              <Link
                href="/login"
                className="inline-flex items-center justify-center gap-2 bg-primary hover:bg-primary-accent text-gray-900 font-bold px-8 py-3 rounded-lg transition-all shadow-glow"
              >
                <ArrowLeft size={16} /> Back to Sign In
              </Link>
            </div>
          ) : (
            /* Form State */
            <>
              <div className="mb-6">
                <div className="w-12 h-12 bg-primary/10 border border-primary/20 rounded-xl flex items-center justify-center mb-4">
                  <Mail size={24} className="text-primary" />
                </div>
                <h2 className="text-xl font-bold text-white mb-1">Forgot Password?</h2>
                <p className="text-gray-400 text-sm leading-relaxed">
                  No worries! Enter your email address and we&apos;ll send you a secure link to reset your password.
                </p>
              </div>

              {/* Error */}
              {pageState === 'error' && errorMsg && (
                <div className="flex items-center gap-2 bg-red-500/10 border border-red-500/30 text-red-400 rounded-lg px-4 py-3 mb-5 text-sm">
                  <AlertCircle size={16} className="shrink-0" />
                  <span>{errorMsg}</span>
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-5">
                <div>
                  <label htmlFor="forgot-email" className="block text-sm font-medium text-gray-300 mb-1.5">
                    Email Address
                  </label>
                  <div className="relative">
                    <Mail size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
                    <input
                      id="forgot-email"
                      type="email"
                      value={email}
                      onChange={(e) => {
                        setEmail(e.target.value);
                        if (pageState === 'error') setPageState('idle');
                      }}
                      placeholder="you@example.com"
                      autoComplete="email"
                      required
                      className="w-full bg-white/5 border border-white/10 text-white placeholder-gray-600 rounded-lg pl-10 pr-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all"
                    />
                  </div>
                </div>

                <button
                  id="forgot-submit-btn"
                  type="submit"
                  disabled={pageState === 'loading'}
                  className="w-full bg-primary hover:bg-primary-accent active:bg-primary-dark text-gray-900 font-bold py-3 rounded-lg transition-all duration-200 flex items-center justify-center gap-2 shadow-glow hover:shadow-[0_0_20px_rgba(255,193,7,0.4)] disabled:opacity-60 disabled:cursor-not-allowed"
                >
                  {pageState === 'loading' ? (
                    <>
                      <Loader2 size={18} className="animate-spin" />
                      <span>Sending Reset Link...</span>
                    </>
                  ) : (
                    <>
                      <Send size={16} />
                      <span>Send Reset Link</span>
                    </>
                  )}
                </button>
              </form>

              <div className="mt-6 pt-6 border-t border-white/10 flex items-center justify-center">
                <Link
                  href="/login"
                  className="flex items-center gap-2 text-sm text-gray-400 hover:text-primary transition-colors font-medium"
                >
                  <ArrowLeft size={15} />
                  Back to Sign In
                </Link>
              </div>
            </>
          )}
        </div>

        {/* Help note */}
        <p className="text-center text-xs text-gray-600 mt-6">
          Need help?{' '}
          <span className="text-gray-500 hover:text-primary cursor-pointer transition-colors">Contact Support</span>
        </p>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Mail, Lock, Eye, EyeOff, Loader2, AlertCircle, CheckCircle2, ArrowLeft } from 'lucide-react';
import { useStore } from '@/store/useStore';
import { getDashboardForRole } from '@/utils/roleRoutes';

export default function LoginPage() {
  const router = useRouter();
  const login = useStore((s) => s.login);

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Please fill in all fields.');
      return;
    }
    setError('');
    setLoading(true);
    try {
      const success = await login(email, password);
      if (success) {
        let userRole = '';
        if (typeof window !== 'undefined') {
          const uStr = localStorage.getItem('zibonbaba_user');
          if (uStr) {
            try { userRole = JSON.parse(uStr).role; } catch (_) {}
          }
        }
        const targetPath = getDashboardForRole(userRole || useStore.getState().role);
        router.push(targetPath);
      } else {
        setError('Invalid email or password. Please try again.');
      }
    } catch {
      setError('Something went wrong. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center relative overflow-hidden bg-neutral-dark">
      {/* Back Button */}
      <Link href="/" className="absolute top-4 left-4 z-50 p-2.5 rounded-full bg-white/5 hover:bg-white/10 text-gray-400 hover:text-white transition-colors border border-white/10 backdrop-blur-sm">
        <ArrowLeft size={20} />
      </Link>

      {/* Animated gradient background */}
      <div className="absolute inset-0 z-0">
        <div className="absolute inset-0 bg-gradient-to-br from-gray-900 via-gray-800 to-gray-950" />
        <div className="absolute top-[-10%] left-[-10%] w-[500px] h-[500px] rounded-full bg-primary/10 blur-[100px] animate-pulse" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[500px] h-[500px] rounded-full bg-primary/5 blur-[120px] animate-pulse" style={{ animationDelay: '1s' }} />
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[300px] h-[300px] rounded-full bg-yellow-400/5 blur-[80px]" />
      </div>

      {/* Decorative grid */}
      <div className="absolute inset-0 z-0 opacity-5"
        style={{
          backgroundImage: 'linear-gradient(rgba(255,193,7,0.3) 1px, transparent 1px), linear-gradient(90deg, rgba(255,193,7,0.3) 1px, transparent 1px)',
          backgroundSize: '40px 40px'
        }}
      />

      <div className="relative z-10 w-full max-w-md px-4 py-10">
        {/* Logo & Branding */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-primary shadow-glow mb-4">
            <span className="text-3xl font-black text-gray-900">Z</span>
          </div>
          <h1 className="text-3xl font-black text-primary tracking-tight">Zibonbaba</h1>
          <p className="text-gray-400 text-sm mt-1">Your Premier Marketplace</p>
        </div>

        {/* Glass Card */}
        <div className="backdrop-blur-xl bg-white/5 border border-white/10 rounded-xl shadow-modal p-8">
          <h2 className="text-xl font-bold text-white mb-1">Welcome back</h2>
          <p className="text-gray-400 text-sm mb-6">Sign in to your account to continue</p>

          {/* Error Banner */}
          {error && (
            <div className="flex items-center gap-2 bg-red-500/10 border border-red-500/30 text-red-400 rounded-lg px-4 py-3 mb-5 text-sm animate-fade-in">
              <AlertCircle size={16} className="shrink-0" />
              <span>{error}</span>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Email */}
            <div>
              <label htmlFor="login-email" className="block text-sm font-medium text-gray-300 mb-1.5">
                Email Address
              </label>
              <div className="relative">
                <Mail size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
                <input
                  id="login-email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="you@example.com"
                  autoComplete="email"
                  className="w-full bg-white/5 border border-white/10 text-white placeholder-gray-600 rounded-lg pl-10 pr-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all"
                />
              </div>
            </div>

            {/* Password */}
            <div>
              <label htmlFor="login-password" className="block text-sm font-medium text-gray-300 mb-1.5">
                Password
              </label>
              <div className="relative">
                <Lock size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
                <input
                  id="login-password"
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••"
                  autoComplete="current-password"
                  className="w-full bg-white/5 border border-white/10 text-white placeholder-gray-600 rounded-lg pl-10 pr-11 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary/50 transition-all"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500 hover:text-gray-300 transition-colors"
                  tabIndex={-1}
                >
                  {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </div>

            {/* Remember me + Forgot */}
            <div className="flex items-center justify-between">
              <label htmlFor="remember-me" className="flex items-center gap-2 cursor-pointer">
                <div className="relative">
                  <input
                    id="remember-me"
                    type="checkbox"
                    checked={rememberMe}
                    onChange={(e) => setRememberMe(e.target.checked)}
                    className="sr-only peer"
                  />
                  <div className="w-4 h-4 border border-white/20 rounded bg-white/5 peer-checked:bg-primary peer-checked:border-primary transition-all flex items-center justify-center">
                    {rememberMe && <CheckCircle2 size={10} className="text-gray-900" />}
                  </div>
                </div>
                <span className="text-sm text-gray-400">Remember me</span>
              </label>
              <Link
                href="/forgot-password"
                className="text-sm text-primary hover:text-yellow-300 transition-colors font-medium"
              >
                Forgot Password?
              </Link>
            </div>

            {/* Login Button */}
            <button
              id="login-submit-btn"
              type="submit"
              disabled={loading}
              className="w-full bg-primary hover:bg-primary-accent active:bg-primary-dark text-gray-900 font-bold py-3 rounded-lg transition-all duration-200 flex items-center justify-center gap-2 shadow-glow hover:shadow-[0_0_20px_rgba(255,193,7,0.4)] disabled:opacity-60 disabled:cursor-not-allowed mt-2"
            >
              {loading ? (
                <>
                  <Loader2 size={18} className="animate-spin" />
                  <span>Signing in...</span>
                </>
              ) : (
                <span>Sign In</span>
              )}
            </button>
          </form>

          {/* Divider */}
          <div className="flex items-center gap-3 my-6">
